9	export interface IsolationResponse {
10	  status: number;
11	  body: any;
12	  text: string;
13	}
14	
15	export interface RequestOptions {
16	  body?: unknown;
17	  headers?: Record<string, string>;
18	}
19	
20	export interface IsolationSuiteDeps {
21	  readonly platformName: string;
22	  createApp(): Promise<{
23	    app: INestApplication;
24	    request: (
25	      method: 'GET' | 'POST',
26	      path: string,
27	      options?: RequestOptions,
28	    ) => Promise<IsolationResponse>;
29	    close: () => Promise<void>;
30	  }>;
31	}
32	
33	/**
34	 * Sequences, failure boundaries and parallel-execution assertions shared
35	 * verbatim by the Express and Fastify adapters: both platforms must expose
36	 * exactly the same per-request isolation behaviour.
37	 */
38	export function registerIsolationSuite(deps: IsolationSuiteDeps): void {
39	  type SendRequest = (
40	    method: 'GET' | 'POST',
41	    path: string,
42	    options?: RequestOptions,
