1	import { IncomingMessage } from 'http';
2	import { Observable } from 'rxjs';
3	import { CONTROLLER_ID_KEY } from '../injector/constants.js';
4	import { ContextId } from '../injector/instance-wrapper.js';
5	import { HeaderStream } from '../router/sse-stream.js';
6	import { ParamProperties } from './context-utils.js';
7	import type { Type } from '@nestjs/common';
8	import type { Controller } from '@nestjs/common/internal';
9	
10	export const HANDLER_METADATA_SYMBOL = Symbol.for('handler_metadata:cache');
11	
12	export type HandleResponseFn = HandlerResponseBasicFn | HandleSseResponseFn;
13	
14	export type HandlerResponseBasicFn = <TResult, TResponse>(
15	  result: TResult,
16	  res: TResponse,
17	  req?: any,
18	) => any;
19	
20	export type HandleSseResponseFn = <
21	  TResult extends Observable<unknown> = any,
22	  TResponse extends HeaderStream = any,
23	  TRequest extends IncomingMessage = any,
24	>(
25	  result: TResult,
26	  res: TResponse,
27	  req: TRequest,
28	) => any;
29	
30	export interface HandlerMetadata {
31	  argsLength: number;
32	  isSseHandler: boolean;
33	  paramtypes: any[];
34	  httpStatusCode: number;
35	  responseHeaders: any[];
36	  hasCustomHeaders: boolean;
37	  aggregateParamErrors: boolean;
38	  getParamsMetadata: (
39	    moduleKey: string,
40	    contextId?: ContextId,
41	    inquirerId?: string,
42	  ) => (ParamProperties & { metatype?: any })[];
43	  fnHandleResponse: HandleResponseFn;
44	}
45	
46	export class HandlerMetadataStorage<
47	  TValue = HandlerMetadata,
48	  TKey extends Type<unknown> = any,
49	> {
50	  private readonly [HANDLER_METADATA_SYMBOL] = new Map<string, TValue>();
51	
